"""Build the self-contained v8 report from the measured JSON tables and figures."""
from build_section_documents import render as render_section_documents
from build_size_normalization import render as render_size_normalization
from pathlib import Path
import json,html,base64,statistics
O=Path(__file__).resolve().parent
load=lambda n:json.loads((O/'data'/f'{n}.json').read_text())
e=lambda x:html.escape(str(x))
def table(rows,keys=None):
 if not rows:return '<p>No eligible observations.</p>'
 keys=keys or list(rows[0]);return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+e(k.replace('_',' '))+'</th>' for k in keys)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(round(r[k],2) if isinstance(r.get(k),float) else r.get(k,''))+'</td>' for k in keys)+'</tr>' for r in rows)+'</tbody></table></div>'
def details(title,rows,keys=None):return '<details><summary>'+e(title)+'</summary>'+table(rows,keys)+'</details>'
s=load('summary');scores=load('score_summary');issues=load('issues');parts=['''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>D4D v8 evaluation summary</title><style>body{font:17px/1.6 system-ui,sans-serif;color:#172033;background:#f5f7fa;margin:0}main{max-width:1180px;margin:auto;padding:38px 24px;background:white}h1{font-size:38px;line-height:1.2}h2{margin-top:50px}h3{margin-bottom:5px}a{color:#166a88}nav{display:flex;gap:18px;flex-wrap:wrap;padding:14px 0;border-block:1px solid #d9e1ea}.cards{display:flex;gap:14px;flex-wrap:wrap}.card{padding:15px 23px;background:#edf3f7;border-radius:8px}.card b{font-size:30px;display:block}.note{background:#fff3d6;padding:18px;border-left:4px solid #bb9140}figure{margin:25px 0;padding:10px;border:1px solid #e0e7ee}figure img{width:100%;height:auto}figcaption{padding:12px;font-size:15px;color:#465366}table{border-collapse:collapse;font-size:14px;width:100%}td,th{padding:9px;border-bottom:1px solid #dce3eb;text-align:left;vertical-align:top}th{background:#eef3f7}.scroll{overflow:auto}summary{cursor:pointer;padding:12px;background:#eef3f7;margin-top:12px}input{padding:12px;width:95%;font-size:16px}.issue{padding:16px;border-bottom:1px solid #dce3eb}.muted{color:#526174;font-size:14px}@media print{details{display:block}nav,input{display:none}figure{break-inside:avoid}}</style><main><p class="muted">D4D semantic evaluation • v8 only • primary ratings</p><h1>Completeness, review concerns, and source relationships</h1><div class="note" id="historical-cohort" data-affected-records="CM4AI_v8_rep2 CM4AI_v8_rep3"><p><strong>Historical cohort: September 2026.</strong> These reports describe frozen generic-v7/v8 records and their September 12 CBORG reference rescore, not the current generator or a current validation of its outputs. Saved render metadata dates v7 to September 1–2 and v8 to September 5 (VOICE replicate 1) or September 7 (the other 11 records). Labels beginning <code>2026-09-04f/g</code> are run identifiers, not the generation dates of all v8 records. Provenance recording timestamps are distinct from exact model-call start times; see the saved <a href="https://github.com/bridge2ai/data-sheets-schema/blob/d2e8b1d3f2cae162c5fb9e3c31c63c9864baf205/data/d4d_concatenated/claudecode_api_core/2026-09-04f_claude-opus-5-api-generic-v8_rep1/VOICE_provenance.yaml">VOICE v8 replicate 1</a> and <a href="https://github.com/bridge2ai/data-sheets-schema/blob/d2e8b1d3f2cae162c5fb9e3c31c63c9864baf205/data/d4d_concatenated/claudecode_api_core/2026-09-04g_claude-opus-5-api-generic-v8_rep2/CM4AI_provenance.yaml">CM4AI v8 replicate 2</a> records.</p><p><strong>CM4AI generation-regime caveat.</strong> V8 replicates 2 and 3 returned no thinking block in the full, reconciliation, report, and report re-check phases. The historical requests omitted the <code>thinking</code> parameter; the <a href="https://github.com/bridge2ai/data-sheets-schema/blob/d2e8b1d3f2cae162c5fb9e3c31c63c9864baf205/notes/generic_v8_analysis_plan.md#L351-L365">generation analysis documents an input-correlated adaptive outcome</a>, not an explicit request to disable thinking or an established proxy fault. Both <a href="https://github.com/bridge2ai/data-sheets-schema/blob/d2e8b1d3f2cae162c5fb9e3c31c63c9864baf205/data/d4d_concatenated/claudecode_api_core/2026-09-04g_claude-opus-5-api-generic-v8_rep2/CM4AI_provenance.yaml">replicate 2</a> and <a href="https://github.com/bridge2ai/data-sheets-schema/blob/d2e8b1d3f2cae162c5fb9e3c31c63c9864baf205/data/d4d_concatenated/claudecode_api_core/2026-09-04g_claude-opus-5-api-generic-v8_rep3/CM4AI_provenance.yaml">replicate 3</a> remain included in every original score and pooled result. The pooled CM4AI comparison therefore mixes observed thinking regimes. This limits attribution of differences to the v8 package alone; it does not establish that the regime explains any score difference or justify a corrected score.</p></div><p>Measurements recomputed for the 12 v8 datasheets: AI_READI, CHORUS, CM4AI, and VOICE, each with three generation replicates and one retained primary evaluation under each rubric. No evaluations were rerun.</p><div class="cards"><div class="card"><b>12</b>datasheets</div><div class="card"><b>24</b>primary evaluations</div><div class="card"><b>303</b>review comments</div><div class="card"><b>14</b>selected figures</div></div><nav><a href="#findings">Findings</a><a href="#scores">Scores</a><a href="#missing">Missingness</a><a href="#reviews">Review concerns</a><a href="#sources">Source relationships</a><a href="#pooled-sections">Pooled section / document profiles</a><a href="#size-normalized">Size-normalized sections</a><a href="#methods">Methods & data</a><a href="#comments">Comment browser</a></nav><h2 id="findings">Main findings</h2><ul><li>AI_READI and VOICE have the highest mean recorded scores under both rubrics; CHORUS has the lowest. The rubrics assess different constructs, so their percentages should be read separately.</li><li>Consistency (105) and completeness (100) account for 205 of 303 comments (67.7%). There are also 36 content-accuracy, 29 correctness, and 33 semantic-understanding comments.</li><li>Among 12 fields selected by v8 absent-field mentions, 106 of 144 record–field pairs are structurally absent; 62 of those absences are mentioned in completeness comments. These selected-field counts are not an overall completeness rate.</li><li>All 12 records have at least one accuracy or correctness flag. The most frequently implicated root is <code>source_caveats</code> (10/12 records); this often reflects a source conflict recorded in the datasheet, rather than an independently established extraction error.</li><li>Source associations differ by dataset and outcome. For example, documentation-linked fields have a +17.6 percentage-point completeness-flag contrast in CM4AI and −15.7 in VOICE. These descriptive contrasts do not identify source effects.</li></ul><div class="note"><b>Interpretation qualification.</b> Seven of the 12 rubric20 evaluations have identified Q19 rationale qualifications; selected CM4AI Q13/version interpretations also need adjudication. Scores below preserve the recorded evaluations. Native “accuracy” and “correctness” labels are review allegations, not verified factual-error rates.</div><h2 id="scores">Recorded scores and rubric profile</h2>''',table(scores,['project','rubric','n','adjusted_mean','adjusted_min','adjusted_max','q19_qualified'])]
figs=[('01_v8_scores','Each point is a generation replicate. Scores use each evaluation’s applicable maximum, preserving N/A decisions. Ranges show observed variation, not confidence intervals. Red rings identify Q19-qualified rubric20 evaluations.'),('02_v8_item_profile','Item profiles localize score losses without treating rubric totals as interchangeable. CHORUS has particularly low recorded Q13 (40%) and Q20 (46.7%) means; CM4AI has 40% means for Q4 and Q11. Applicability counts and original question names are available below.'),('03_v8_missingness','Root fields are counted as populated when their value is neither null, an empty string, an empty list, nor an empty map; false and zero remain populated. Nested completeness is not assessed by this structural measure. download_url and imputation_protocols are absent from all 12 records, but were mentioned in 9 and 7 records respectively. Absence alone does not establish that a field should have been populated.'),('04_v8_comment_types','Counts retain native reviewer labels and all 303 primary issue entries. Equal review counts per dataset make the exposure comparable, but comments may combine multiple concerns or repeat concerns across the two rubrics.'),('05_v8_sections','Each record contributes at most once to each section–type cell across both rubrics. A multi-field comment can contribute to multiple sections. Sections follow the retained schema crosswalk, not a manual reclassification of review prose.'),('06_v8_accuracy_fields','Fields are implicated when named in a correctness or content_accuracy comment, whether they are the disputed value, context, or a caveat documenting disagreement. Top roots are selected using v8 only; these counts do not establish which fields are factually wrong.'),('07_v8_source_sections','Coverage receipts describe which source chunks support datasheet roots/sections. Each cell counts unique v8 records with at least one declared link; repeated chunks do not inflate prevalence. The eight document families combine the explicit native types shown below. Presence demonstrates documented linkage, not verified entailment.'),('08_v8_source_associations','Positive values mean more flagged fields among fields linked to the named source type; negative values mean fewer. For each record and schema section, compare populated receipt-linked roots linked to the source type with other populated receipt-linked roots. Include only sections with both groups, average equally over eligible sections, then over eligible records. Groups can also be linked to other source types; this is not a mutually exclusive source comparison. N/A means no eligible comparison, not zero association.')]
for i,(name,cap) in enumerate(figs):
 if i==2:parts.append('<h2 id="missing">Structural absence and review omissions</h2>')
 if i==3:parts.append('<h2 id="reviews">Types, sections, and implicated fields</h2>')
 if i==6:parts.append('<h2 id="sources">Source documentation and review associations</h2>')
 b64=base64.b64encode((O/'figures'/f'{name}.png').read_bytes()).decode();parts.append(f'<figure><img alt="{e(name.replace("_"," "))}" src="data:image/png;base64,{b64}"><figcaption><b>Figure {i+1}.</b> {cap} <a href="figures/{name}.svg">SVG</a> · <a href="figures/{name}.png">PNG</a></figcaption></figure>')
 if i==1:parts.append(details('All rubric20 items: applicability and full / partial / zero scores',load('rubric20_profile')))
 if i==7:
  parts.append(details('Source-type grouping', [{'native_type':k,'display_family':v} for k,v in load('source_group_mapping').items()]))
  parts.append(details('Association estimates and eligible record counts',load('source_associations')))
parts.append(render_section_documents(table,details))
parts.append(render_size_normalization(table,details))
parts.append(f'''<h2 id="methods">Methods, sensitivity, and reproducibility</h2><p>All figures use v8 primary ratings only. No v7 observations, repeat ratings, pooled-cohort p-values, or pooled manual-adjudication sample rates enter this report. The 840 item records comprise 50 rubric10 subelements and 20 rubric20 questions per datasheet. Reported score means give each generation replicate equal weight.</p><p>The three generations per dataset share a dataset and source context. They do not provide three independent dataset samples. With only four datasets and sparse, unequal source comparisons, this report emphasizes observed variation and effect sizes; it does not add inferential significance tests. Selected missing fields and accuracy roots are exploratory, chosen using these same v8 observations.</p><p>The {s['receipt_links']:,} retained receipt links include {s['receipt_links_unpopulated_roots']} links to structurally unpopulated roots. Figure 7 retains declared links; Figure 8 restricts its comparison universe to populated roots. The latter can therefore miss omission problems involving entirely absent fields. Source availability, field selection, topic difficulty, and review behavior remain possible explanations for the observed contrasts.</p><p>Cross-rubric overlap below measures agreement in flagged field sets, not reviewer reliability or factual validity. Removing Q19, or Q13 and Q19, is an item-omission sensitivity analysis, not a corrected score or an adjudication. Historical schema conventions matter: a bare DOI can be valid, and a landing page does not necessarily satisfy a direct <code>download_url</code>.</p>''')
parts.append(details('Rubric20 item-omission sensitivity (all 12 records)',load('score_sensitivity')))
parts.append(details('Cross-rubric flagged-field overlap (typed = review family plus field)',load('cross_rubric_agreement')))
parts.append(details('Rubric10 element profile',load('rubric10_elements')))
parts.append(details('Severity counts',load('severity_counts')))
parts.append('<p>Input and evaluation SHA-256 hashes were rechecked for all 24 evaluations, and all 24 score/denominator totals were reconciled to applicable items. Historical source recovery provenance and schema section mapping are retained in the data. Repository qualifications originate in <code>notes/reference_rescore_2026-09-12_cborg_runtime/</code>.</p><p><a href="README.txt">README and reproduction instructions</a> · <a href="analyze_v8.py">Measurement script</a> · <a href="build_report.py">Report script</a> · <a href="data/validation.json">Validation</a></p><details><summary>Download measurement tables (JSON)</summary><ul>')
for f in sorted((O/'data').glob('*.json')):parts.append(f'<li><a href="data/{f.name}">{e(f.stem)}</a></li>')
parts.append('</ul></details><h2 id="comments">Search the 303 v8 review comments</h2><p>Original review descriptions and recommendations are reproduced for inspection. They remain reviewer claims; recommendations have not been automatically adopted.</p><input id="search" aria-label="Search comments" placeholder="Search dataset, field, type, severity, or wording"><p id="count">303 comments</p><div id="issues">')
for x in issues:
 parts.append('<article class="issue"><b>'+e(x['record'])+' · R'+str(x['rubric'])+' · '+e(x['type'])+' · '+e(x['severity'])+'</b><p class="muted">'+e(x['issue_id'])+' | Fields: '+e(', '.join(x['fields']))+'</p><p>'+e(x['description'])+'</p><p><b>Reviewer recommendation:</b> '+e(x['recommendation'])+'</p></article>')
parts.append('''</div><script>document.getElementById('search').addEventListener('input',function(){let n=0;const q=this.value.toLowerCase();document.querySelectorAll('.issue').forEach(x=>{const show=x.textContent.toLowerCase().includes(q);x.hidden=!show;if(show)n++});document.getElementById('count').textContent=n+' of 303 comments'});</script></main></html>''')
(O/'D4D_v8_summary.html').write_text(''.join(parts))
